import { tags } from "typia";

import { IEShoppingMallActorType } from "./IEShoppingMallActorType";

/**
 * Aggregated authentication statistics for a single actor type over a given
 * analysis window.
 *
 * @autobe Generated by AutoBE - https://github.com/wrtnlabs/autobe
 */
export type IShoppingMallAuthenticationActorTypeSummary = {
  /**
   * Actor classification for which these metrics are computed (for example,
   * customer, seller, platformAdmin, guestUser).
   */
  actorType: IEShoppingMallActorType;

  /**
   * Total number of authentication attempts (successful and failed) performed
   * by this actor type during the analysis window.
   */
  totalAttempts: number & tags.Type<"int32">;

  /**
   * Number of successful authentication attempts for this actor type during
   * the analysis window.
   */
  successfulAttempts: number & tags.Type<"int32">;

  /**
   * Number of failed authentication attempts for this actor type during the
   * analysis window.
   */
  failedAttempts: number & tags.Type<"int32">;
};
